'use strict';
const $=s=>document.querySelector(s);
const illustrations={tray:'<ellipse cx="150" cy="135" rx="115" ry="48" fill="#a76643"/><ellipse cx="150" cy="122" rx="115" ry="48" fill="#c48c61"/><ellipse cx="150" cy="122" rx="92" ry="32" fill="#dab18a"/><rect x="117" y="103" width="58" height="27" rx="7" fill="#f3efe1" transform="rotate(-12 140 120)"/>',mat:'<path d="M25 90L213 47L281 151L80 200Z" fill="#819178"/><path d="M25 84L213 41L281 145L80 194Z" fill="#a4b098"/><rect x="110" y="83" width="88" height="51" rx="4" fill="#eeeadd" transform="rotate(-12 140 100)"/><path d="M120 93L185 79M123 104L188 90M126 115L191 101" stroke="#c1c3b3" stroke-width="5"/>',clips:'<g fill="#d1ac8a" stroke="#a78162" stroke-width="2"><rect x="28" y="84" width="68" height="58" rx="21"/><rect x="115" y="70" width="68" height="58" rx="21"/><rect x="202" y="56" width="68" height="58" rx="21"/></g><g fill="#554b40"><ellipse cx="62" cy="97" rx="13" ry="9"/><ellipse cx="149" cy="83" rx="13" ry="9"/><ellipse cx="236" cy="69" rx="13" ry="9"/></g><path d="M62 97C63 174 143 122 150 199" stroke="#eee8d9" stroke-width="9" fill="none"/>'};
const products=[{id:'tray',name:'Everyday catchall',category:'Organize',price:24,tag:'A place for the little things',description:'Concept: a compact tray for small desk essentials. Dimensions, material, finish and supplier are not yet verified.'},{id:'mat',name:'Quiet desk mat',category:'Workspace',price:29,tag:'Give your workspace a little breathing room',description:'Concept: a desk mat to define your workspace. Dimensions, material, durability and supplier are not yet verified.'},{id:'clips',name:'Cable keeper set',category:'Organize',price:14,tag:'Bring loose ends together',description:'Concept: a small set of cable organizers. Pack quantity, compatibility, adhesive and supplier are not yet verified.'}];
const plan=[['1','Desk reset','Show your actual desk before and after a 30-second tidy.','Save this for your next desk reset.'],['2','One small habit','Give keys, earbuds and cables a dedicated place.','Which item always goes missing on your desk?'],['3','Behind the concept','Explain why you are building a small workspace collection.','Follow along as we test the collection.'],['4','Sample review','Film a real sample: dimensions, finish and one limitation.','What would you like us to test next?'],['5','Cable routine','Demonstrate a cable organizer only after testing a real sample.','Save this simple setup idea.'],['6','Small-space tour','Show three organization ideas using items you already own.','Share your favorite small-space tip.'],['7','Community feedback','Compare two actual layouts and ask which feels calmer.','A or B? Tell us why.']];
const steps=['Confirmar país da empresa e provedor de pagamento elegível.','Pesquisar demanda e concorrentes com fontes e datas.','Validar fornecedor, custo entregue, estoque e devoluções.','Testar uma amostra e confirmar prazo real de entrega.','Substituir ilustrações e preços por dados reais autorizados.','Definir políticas, contato comercial e obrigações aplicáveis.','Conectar pagamento e testar compra, cancelamento e reembolso.','Conectar pedidos e rastreamento ao fornecedor.','Definir capital de giro e limites de gasto.','Validar marca/domínio e publicar para o público desejado.'];
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
function read(key,fallback){try{return JSON.parse(localStorage.getItem('tidyfolk-'+key))??fallback}catch{return fallback}}
function write(key,value){try{localStorage.setItem('tidyfolk-'+key,JSON.stringify(value))}catch{toast('Storage unavailable: changes will last only this session.')}}
let cart=read('cart',{});if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};for(const k of Object.keys(cart))if(!products.some(p=>p.id===k)||!Number.isInteger(cart[k])||cart[k]<1||cart[k]>99)delete cart[k];
let orders=read('orders',[]);if(!Array.isArray(orders))orders=[];orders=orders.filter(o=>o&&typeof o.id==='string'&&typeof o.date==='string'&&Number.isFinite(o.total)&&o.total>=0&&Array.isArray(o.items));
let checks=read('checks',[]);if(!Array.isArray(checks))checks=[];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function art(id){return '<svg viewBox="0 0 300 240" role="img" aria-label="Concept illustration, not a product photograph">'+illustrations[id]+'</svg>'}
function renderProducts(filter='all'){$('#products').innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="product"><button class="product-art" data-detail="${p.id}" aria-label="View ${p.name}">${art(p.id)}</button><div class="product-meta"><h3>${p.name}</h3><span>${money(p.price)}</span></div><p>${p.tag}</p><button class="add" data-add="${p.id}">Add to demo bag +</button></article>`).join('')}
function subtotal(){return products.reduce((s,p)=>s+p.price*(cart[p.id]||0),0)}
function renderCart(){$('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);$('#cartItems').innerHTML=products.filter(p=>cart[p.id]).map(p=>`<div class="cart-row"><div><strong>${p.name}</strong><span>${money(p.price*cart[p.id])}</span></div><div class="quantity"><button data-qty="${p.id}" data-delta="-1" aria-label="Decrease ${p.name}">−</button><span>${cart[p.id]}</span><button data-qty="${p.id}" data-delta="1" aria-label="Increase ${p.name}">+</button><button class="text-btn" style="width:auto;border:0;background:none" data-remove="${p.id}">Remove</button></div></div>`).join('')||'<p>Your demo bag is empty. Explore the collection to get started.</p>';$('#total').textContent=money(subtotal());$('#simulate').disabled=!Object.keys(cart).length;write('cart',cart)}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function renderOps(){$('#orderCount').textContent=orders.length;$('#revenue').textContent=money(orders.reduce((s,o)=>s+o.total,0));$('#orders').innerHTML=orders.slice().reverse().map(o=>`<div class="order"><strong>${esc(o.id)} · ${money(o.total)}</strong><span>${esc(new Date(o.date).toLocaleString('pt-BR'))} · Simulado, não enviado ao fornecedor</span></div>`).join('')||'<p>Nenhum pedido simulado. Experimente adicionar produtos à sacola.</p>';$('#checklist').innerHTML=steps.map((s,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${checks.includes(i)?'checked':''}><span>${s}</span></label>`).join('');$('#progress').textContent=`${steps.filter((_,i)=>checks.includes(i)).length} de ${steps.length} etapas anotadas como concluídas.`}
function calculate(){const vals=['sale','cost','shipping','fees','returns','ads'].map(id=>Number($('#'+id).value));if(vals.some(v=>!Number.isFinite(v)||v<0)){$('#margin').textContent='Informe valores válidos e não negativos.';$('#breakeven').textContent='';return}const [sale,cost,shipping,fees,returns,ads]=vals;const before=sale-cost-shipping-fees-returns;const margin=before-ads;$('#margin').textContent=`Contribuição por pedido: ${money(margin)}${sale>0?' ('+(100*margin/sale).toFixed(1)+'%)':''}`;$('#breakeven').textContent=before>=0?`Publicidade máxima para zerar esta contribuição: ${money(before)} por venda. Ainda faltam custos fixos e impostos aplicáveis.`:'Os custos informados já superam o preço, mesmo sem publicidade.'}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.add){const id=b.dataset.add;cart[id]=Math.min(99,(cart[id]||0)+1);$('#cartMessage').textContent='';renderCart();toast('Added to your demo bag')}if(b.dataset.detail){const p=products.find(p=>p.id===b.dataset.detail);$('#productTitle').textContent=p.name;$('#productDetail').innerHTML=`<div class="product-art">${art(p.id)}</div><p>${p.description}</p><strong>${money(p.price)} · illustrative price</strong><p class="notice">No stock, shipping or availability is confirmed.</p><button class="primary" data-add="${p.id}">Add to demo bag +</button>`;$('#productDialog').showModal()}if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderProducts(b.dataset.filter)}if(b.dataset.qty){const id=b.dataset.qty;cart[id]=Math.min(99,(cart[id]||0)+Number(b.dataset.delta));if(cart[id]<=0)delete cart[id];renderCart()}if(b.dataset.remove){delete cart[b.dataset.remove];renderCart()}if(b.dataset.tab){document.querySelectorAll('.tab').forEach(x=>x.hidden=x.id!==b.dataset.tab);document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b))}});
$('#cartOpen').onclick=()=>{$('#cartMessage').textContent='';renderCart();$('#cartDialog').showModal()};$('#opsOpen').onclick=()=>{renderOps();$('#opsDialog').showModal()};
$('#simulate').onclick=()=>{if(!Object.keys(cart).length)return;const order={id:'DEMO-'+Date.now().toString(36).toUpperCase(),date:new Date().toISOString(),total:subtotal(),status:'simulation_only',items:products.filter(p=>cart[p.id]).map(p=>({id:p.id,name:p.name,quantity:cart[p.id],unitPrice:p.price}))};orders.push(order);write('orders',orders);cart={};renderCart();renderOps();$('#cartMessage').textContent=`${order.id} saved in this browser. No payment taken; no order sent. View it in Painel de operação.`};
$('#exportOrders').onclick=()=>download('tidyfolk-demo-orders.json',JSON.stringify({demoOnly:true,orders},null,2),'application/json');
$('#reset').onclick=()=>{if(!confirm('Apagar carrinho, pedidos simulados e checklist deste navegador?'))return;cart={};orders=[];checks=[];write('orders',orders);write('checks',checks);renderCart();renderOps();toast('Dados de demonstração apagados')};
$('#checklist').onchange=e=>{if(e.target.dataset.check===undefined)return;const n=Number(e.target.dataset.check);checks=checks.filter(v=>v!==n);if(e.target.checked)checks.push(n);write('checks',checks);renderOps()};
$('#contentPlan').innerHTML=plan.map(row=>`<div class="content-row"><strong>Dia ${row[0]} · ${row[1]}</strong><p>${row[2]}</p><em>${row[3]}</em></div>`).join('');
$('#exportContent').onclick=()=>download('tidyfolk-content-calendar.csv','\uFEFF'+[['Day','Topic','Script','CTA'],...plan].map(row=>row.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');
document.querySelectorAll('.form-grid input').forEach(input=>input.addEventListener('input',calculate));renderProducts();renderCart();renderOps();calculate();
